const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '../..');
const ev = (file, line, detail) => ({ file: `apps/web/src/${file}`, line, detail });
const findings = [];
function add(id, severity, category, criterion, title, issue, evidence, surfaces, snippet, acceptance, nielsen, law, measurements = null) {
  findings.push({ id: `W-S-${String(id).padStart(3, '0')}`, severity, category, criterion, title, issue, evidence, affected_surfaces: surfaces, measurements, confidence: 'verified_static', status: 'FAIL_STATIC', runtime_status: 'UNKNOWN_NOT_EXERCISED_BY_STATIC_AGENT', fix: { scope: 'Illustrative local change only; report recommendation, not implemented', snippet }, acceptance_verification: acceptance, nielsen, law_diagnosis: law });
}
add(1,'P1','accessibility','WCAG 2.1.1 / 2.4.3; kz N1','Most operational dialogs do not establish modal keyboard behavior',
  'Create/edit overlays are fixed divs without a named dialog role, focus transfer, Tab containment, Escape handling or focus restoration. Container 360 has role/aria-modal/name but still has no focus mechanism. The modal panel can therefore open while keyboard focus remains on its opener outside the panel; aria-modal alone does not move or contain focus. Background scroll/click leakage must be measured separately. Yard dialogs are excluded because their source implements these behaviors.',
  [ev('components/TruckVisitsView.tsx',159,'Create overlay and panel are divs; component imports useState only and contains no focus/key handlers.'),ev('components/BillingView.tsx',398,'Tariff overlay; same structure at 436,477,522.'),ev('components/ManifestsView.tsx',373,'Create overlay; MBL 470 and HBL 514 are also plain div overlays.'),ev('components/ContainersView.tsx',321,'Container 360 role/name exist; no focus/keydown implementation in file.'),ev('components/ContainersView.tsx',897,'Create Visit plain div overlay.'),ev('components/GatePassView.tsx',347,'Issue overlay.'),ev('components/HandoversView.tsx',424,'Create overlay.'),ev('components/MasterDataView.tsx',152,'Create overlay.'),ev('components/UsersRolesView.tsx',146,'Create overlay.'),ev('components/PartnerManagementView.tsx',151,'Create partner overlay.')],
  ['Manifest create/MBL/HBL','Container create/360','Truck Visit create','Billing tariff/rule/order/payment','Gate Pass issue','Handover create','Master Data create','Users create','Partner create'],
  `const dialogRef = useRef<HTMLDialogElement>(null);\nuseEffect(() => {\n  if (!showCreateModal) return;\n  const opener = document.activeElement as HTMLElement | null;\n  const main = document.querySelector<HTMLElement>('.app-content');\n  const overflow = main?.style.overflow ?? '';\n  if (main) main.style.overflow = 'hidden';\n  dialogRef.current?.showModal();\n  return () => {\n    if (main) main.style.overflow = overflow;\n    if (opener?.isConnected) opener.focus();\n  };\n}, [showCreateModal]);\n<dialog ref={dialogRef} aria-labelledby="truck-create-title"\n  onCancel={() => setShowCreateModal(false)}\n  className="m-auto w-full max-w-md rounded-xl bg-white p-6 backdrop:bg-slate-900/40">\n  <h3 id="truck-create-title">Tạo Lịch hẹn Chuyến xe</h3>\n  {/* Existing form and explicitly named Cancel button */}\n</dialog>`,
  ['Open each overlay with keyboard; focus enters a meaningful enabled control.','Tab and Shift+Tab remain in the modal; Escape closes when no write is pending.','On close, focus returns to the opener; background neither scrolls nor receives clicks.'],['H3','H4'],{principle:'Jakob',friction:'The overlay looks modal but does not follow expected modal keyboard conventions.',change:'Use native showModal behavior or the existing project focus pattern, with scroll lock.'});
add(2,'P1','accessibility','WCAG 1.3.1 / 3.3.2 / 4.1.2; kz form check','Visible sibling labels are not associated with operational fields',
  'Several form fields render label and input/select as siblings with no htmlFor/id relationship, no wrapping label and no aria-label/labelledby. Their nearby visible labels do not programmatically name those controls. The unambiguous examples below have no placeholder fallback either. Login, Gate-in and Yard wrapping labels are correct; Gate Pass receiver fields and Container master selectors already have aria-label and are not claimed unnamed.',
  [ev('components/TruckVisitsView.tsx',188,'Plate visible label followed by unnamed input at 189; driver 200/201, phone 210/211, transporter 222/223 and container 232/233 also lack associations.'),ev('components/MasterDataView.tsx',157,'Name label and input at 158; additional code/tax/phone/address/email follow same structure.'),ev('components/UsersRolesView.tsx',151,'Name label/input at 152 and email 155/156.'),ev('components/BillingView.tsx',532,'Payment amount label/input 533; payment method 543/544; tariff/rule/order fields likewise.'),ev('components/HandoversView.tsx',433,'Transport code label/input 434 and three selects 444/445,460/461,475/476.'),ev('components/ManifestsView.tsx',519,'HBL label/input 520, consignee 523/524, agent 527/528, description 531/532, numeric 536/537,540/541.'),ev('components/ContainersView.tsx',686,'Inline Gate Pass labels/input 687,695/696,704/705; Seal 951/952 and weight 955/956.')],
  ['Truck Visit form','Master Data forms','User form','Billing forms','Handover form','Manifest/MBL/HBL forms','Container create/inline Gate Pass/Hold forms'],
  `<label className="block font-semibold text-slate-700">\n  <span className="mb-1 block">Biển số đầu kéo *</span>\n  <input type="text" required value={plate}\n    onChange={(event) => setPlate(event.target.value)}\n    className="w-full rounded-lg border border-slate-300 px-3 py-2 uppercase" />\n</label>\n{/* Apply the same wrapping label or htmlFor/id pair to each field. */}`,['Inspect accessible names for every visible input/select/textarea; each must match its visible label.','Click/tap a visible label and confirm the corresponding control receives focus.','Do not add redundant ARIA to already correctly labelled native fields.'],['H4','H6'],{principle:'Gestalt proximity / Jakob',friction:'Visual proximity implies a label relationship that assistive technology cannot use.',change:'Make the native label relationship explicit.'});
add(3,'P1','accessibility','WCAG 2.1.1 / 4.1.2; kz focus check','Five master/detail lists use pointer-only clickable div cards',
  'The record selectors are divs with onClick and cursor-pointer but no native interactive element, tabIndex or keyboard handler. They cannot receive sequential keyboard focus, so keyboard users cannot choose the record whose detail and subsequent actions are displayed. This is a concrete non-native interaction failure, not a missing-ARIA guess.',
  [ev('components/ManifestsView.tsx',209,'Manifest card onClick at 211.'),ev('components/HandoversView.tsx',214,'Handover card onClick at 216.'),ev('components/GatePassView.tsx',204,'Gate Pass card onClick at 206.'),ev('components/EDIView.tsx',208,'Outbox card onClick at 210.'),ev('components/PartnerManagementView.tsx',246,'Partner log card onClick at 248.')],['Manifest list','Handover list','Gate Pass list','EDI Outbox list','Partner API log list'],
  `<button type="button" key={edi.id}\n  onClick={() => setSelectedEdiId(edi.id)}\n  aria-pressed={selectedEdi?.id === edi.id}\n  className="block w-full rounded-xl border border-slate-200 bg-white p-4 text-left">\n  <span className="block font-mono text-xs font-bold text-blue-700">{edi.messageType}</span>\n  <span className="mt-1 block font-mono text-xs text-slate-800">{edi.containerNumber}</span>\n  <span className="mt-2 block text-xs text-slate-500">{edi.shippingLine}</span>\n</button>`,['Every record selector appears in sequential keyboard order.','Enter and Space select the same record as a pointer click and expose selected state.','Focus is visible and selected detail identifies the chosen record.'],['H3','H4','H7'],{principle:'Jakob',friction:'Cards visually promise a selection control but lack standard button keyboard operation.',change:'Use a native button with preserved card styles.'},{verified_selector_patterns:5});
add(4,'P1','states','kz F3 / A1; form recovery','Two create dialogs discard input before the save result arrives',
  'Master Data dispatches a Promise and immediately resets all fields and closes the panel. Users create similarly calls createManagedUser without awaiting and clears/closes. A delayed or failed request therefore loses the entered data and removes the local recovery surface. AppContext.command does show the global apiError banner on failure, so this finding does not claim errors are absent everywhere.',
  [ev('components/MasterDataView.tsx',36,'Four create Promises at 38-41; unconditional reset/close at 42-43.'),ev('components/UsersRolesView.tsx',176,'createManagedUser at 178, reset/close at 179-180.'),ev('context/AppContext.tsx',445,'command awaits executeOperation; failed writes set global apiError at 448.')],['All four Master Data create types','Add User'],
  `const [pending, setPending] = useState(false);\nconst [formError, setFormError] = useState('');\nconst handleCreateUser = async () => {\n  if (pending) return;\n  setPending(true); setFormError('');\n  try {\n    const result = await createManagedUser(userForm.name.trim(), userForm.email.trim(), userForm.roleCodes);\n    if (!result.success) { setFormError(result.message); return; }\n    setUserForm({ name: '', email: '', roleCodes: [] });\n    setShowUserForm(false);\n  } finally { setPending(false); }\n};\n{formError && <p role="alert" className="text-rose-700">{formError}</p>}\n<button disabled={pending} onClick={() => void handleCreateUser()}>\n  {pending ? 'Đang lưu…' : 'Tạo'}\n</button>`,['Delay a save in a disposable fixture: keep panel and values until outcome.','Reject save: show actionable local error, preserve all input, allow retry.','Resolve save: reset/close only after success and show confirmation.'],['H1','H3','H9'],{principle:'Peak-End / Zeigarnik',friction:'The apparent ending precedes the server outcome and erases unfinished work.',change:'Await outcome and preserve the form on failure.'});
add(5,'P1','states','kz A1; duplicate-submit prevention','Payment and other asynchronous actions stay enabled while saving',
  'Billing payment submission awaits recordPayment but never sets a pending state or guards re-entry, and its submit remains enabled. Repeated clicks/Enter can start multiple calls before the first settles. Context recordPayment creates a new referenceNo with crypto.randomUUID on every call. This proves distinct outgoing command attempts, not that the backend necessarily accepts or duplicates them. Truck/Partner/Handover create and multiple EDI actions also omit pending protection; Yard and Gate-in already protect writes.',
  [ev('components/BillingView.tsx',88,'Payment handler lacks re-entry/pending guard.'),ev('components/BillingView.tsx',562,'Payment submit has no disabled/pending label.'),ev('context/AppContext.tsx',489,'recordPayment sends a newly generated WEB reference per call.'),ev('components/TruckVisitsView.tsx',42,'Create handler and submit at 250 have no pending guard.'),ev('components/PartnerManagementView.tsx',47,'Create and key rotation have no pending guard.'),ev('components/HandoversView.tsx',78,'Create/publish/confirm await without operation pending state.')],['Record Payment','Truck Visit create','Partner create/key rotation','Handover create/publish/confirm','EDI retry/dispatch'],
  `const paymentPending = useRef(false);\nconst [isPaying, setIsPaying] = useState(false);\nconst handleRecordPayment = async (event: React.FormEvent) => {\n  event.preventDefault();\n  if (!selectedInvoice || paymentPending.current) return;\n  paymentPending.current = true; setIsPaying(true);\n  try {\n    const result = await recordPayment(selectedInvoice.id, payAmount, payMethod);\n    if (!result.success) { setPaymentError(result.message); return; }\n    setShowPayModal(false); setSelectedInvoice(null);\n  } finally { paymentPending.current = false; setIsPaying(false); }\n};\n<button type="submit" disabled={isPaying}>\n  {isPaying ? 'Đang ghi nhận…' : 'Xác nhận Thu tiền'}\n</button>`,['Use a delayed fixture, activate submit repeatedly, and observe exactly one command attempt.','The control acknowledges pending immediately and prevents edits/closure that would misidentify the request.','Failure restores enabled retry with preserved values; backend idempotency remains a separate contract.'],['H1','H5'],{principle:'Doherty / Peak-End',friction:'No operation-specific acknowledgment encourages a repeated action before completion.',change:'Expose pending feedback and guard re-entry; p95 latency is still UNKNOWN.'});
add(6,'P2','forms','WCAG 3.3.1 / 3.3.3; kz F1 / F2','Several required-field failures silently return and cannot identify the field',
  'Master Data blank name, Users blank name/email, MBL blank number and HBL blank number/consignee silently return. These panels use div + onClick rather than a native required form, so the visible asterisk does not provide browser validation. Users/Master Data email inputs also default to text. No invalid/error association or first-invalid focus is provided in these paths. This is verified from the handlers and control markup; no submit was exercised.',
  [ev('components/MasterDataView.tsx',37,'Blank name returns without message; input 158 has no required.'),ev('components/UsersRolesView.tsx',177,'Blank required fields return silently; email input at 156 has no type=email.'),ev('components/ManifestsView.tsx',496,'Blank MBL number returns silently.'),ev('components/ManifestsView.tsx',549,'Blank HBL/consignee returns silently.'),ev('components/ContainersView.tsx',793,'Blank hold reason returns silently.')],['Master Data create','Users create','Manifest MBL/HBL add','Container add Hold'],
  `const nameRef = useRef<HTMLInputElement>(null);\nconst [nameError, setNameError] = useState('');\nconst save = async () => {\n  if (!form.name.trim()) {\n    setNameError('Nhập tên trước khi lưu.');\n    nameRef.current?.focus(); return;\n  }\n  await handleCreate();\n};\n<label htmlFor="master-name">Tên *</label>\n<input id="master-name" ref={nameRef} required value={form.name}\n  aria-invalid={!!nameError} aria-describedby={nameError ? 'master-name-error' : undefined}\n  onChange={e => { setForm({ ...form, name: e.target.value }); setNameError(''); }} />\n{nameError && <p id="master-name-error" role="alert">{nameError}</p>}\n<button type="button" onClick={() => void save()}>Lưu</button>`,['Submit blank required values: visible error names each missing field and focus lands on first invalid field.','Invalid email uses type=email or equivalent accessible validation; phone uses type=tel where applicable.','Correcting input clears its stale error; error text is linked with aria-describedby and invalid state.'],['H5','H9'],{principle:'Postel / Peak-End',friction:'A refused save offers no explanation or local recovery path.',change:'Add explicit field-specific validation with preserved input and focus.'});
add(7,'P2','accessibility','WCAG 4.1.2; selection state','Role/permission buttons expose selection only through color',
  'Permission codes in the role editor and role chips in Add User are native named buttons, but their selected state is rendered only through CSS color/border. No aria-pressed/checked state is attached. Similar top-level local view toggles in Billing, Master Data, EDI and Users/Roles use color-only active state. Native buttons are correct for actions; a tablist is not required if these controls remain a button group with explicit pressed state.',
  [ev('components/UsersRolesView.tsx',129,'Permission button selection active at 127/132 has no aria-pressed.'),ev('components/UsersRolesView.tsx',162,'User role chips have no selected state despite includes(...) style at 165.'),ev('components/BillingView.tsx',142,'Invoices/Orders/Tariffs local view buttons.'),ev('components/MasterDataView.tsx',123,'Category view button active only in classes.'),ev('components/EDIView.tsx',74,'Outbox/Routes/Alerts active only in classes.')],['Role permissions','Add User roles','Billing local views','Master Data categories','EDI local views','Users/Roles views'],
  `<button type="button" key={code}\n  aria-pressed={active}\n  onClick={() => setRolePermissions(r.id, active\n    ? r.permissionCodes.filter(item => item !== code)\n    : [...r.permissionCodes, code])}\n  className={active ? 'bg-blue-600 text-white' : 'bg-white text-slate-500'}>\n  {code}\n</button>`,['Accessibility tree exposes true/false selected state for every toggle.','Keyboard selection updates the state and visible styling together.','If a full tablist is adopted, implement its complete roles and keyboard behavior rather than roles alone.'],['H1','H4'],{principle:'Gestalt similarity',friction:'Only sighted users receive the repeated selected-state pattern.',change:'Pair selected styles with programmatic state.'});
add(8,'P1','microcopy','kz A4; honest operational status','Gate Pass detail contradicts expiration and cancellation status',
  'The list derives EXPIRED when an ACTIVE pass expires, but detail badge/actions use only status === ACTIVE and still invite Gate-out. For every non-ACTIVE status, detail copy says the pass was used and offers the Handover next action, including CANCELLED or EXPIRED. Container 360 also locates any ACTIVE pass without expiry and labels it currently valid. Backend rechecks Gate-out; the finding is contradictory UI guidance, not bypassed enforcement.',
  [ev('components/GatePassView.tsx',202,'List computes isExpired and displays EXPIRED at 224.'),ev('components/GatePassView.tsx',247,'Detail badge renders raw status.'),ev('components/GatePassView.tsx',300,'All non-ACTIVE statuses get used copy; ACTIVE always receives Gate-out buttons.'),ev('components/ContainersView.tsx',117,'Active pass lookup omits expiry.'),ev('components/ContainersView.tsx',662,'Unconditionally calls found ACTIVE pass currently valid.')],['Gate Pass list/detail','Container 360 Gate Pass'],
  `const expired = !!selectedGatePass && new Date(selectedGatePass.expiresAt).getTime() <= Date.now();\nconst usable = selectedGatePass?.status === 'ACTIVE' && !expired;\nconst displayedStatus = expired && selectedGatePass?.status === 'ACTIVE'\n  ? 'EXPIRED' : selectedGatePass?.status;\nconst statusCopy = displayedStatus === 'USED'\n  ? 'Phiếu đã được sử dụng để ra cổng.'\n  : displayedStatus === 'CANCELLED' ? 'Phiếu đã bị hủy.'\n  : displayedStatus === 'EXPIRED' ? 'Phiếu đã hết hạn; cần phát hành lại nếu đủ điều kiện.'\n  : 'Đối chiếu thông tin trước khi xác nhận ra cổng.';\n<p>{statusCopy}</p>\n{usable && <button onClick={() => handleConfirmExit(selectedGatePass!)}>Xác nhận Ra cổng</button>}`,['Fixture ACTIVE fresh/ACTIVE expired/USED/CANCELLED/EXPIRED cases: list and detail status agree.','Expired/cancelled passes have appropriate recovery text and no active Gate-out invitation.','Container 360 validity claim also considers expiry; backend remains authoritative.'],['H1','H2','H5'],{principle:'Peak-End / Jakob',friction:'A terminal/restricted record is described as a successful or usable one.',change:'Derive one display status and render distinct status copy/actions.'});
add(9,'P1','states','Functional affordance / truthful output','Container 360 displays an icon where it promises a Gate Pass QR code',
  'The inline Gate Pass display uses Lucide QrCode, which draws a fixed icon unrelated to qrToken. It cannot encode the issued token. The dedicated Gate Pass view already uses react-qr-code with the token, so the same business artifact appears scannable in one screen and as a decorative symbol in another.',
  [ev('components/ContainersView.tsx',668,'QrCode icon at 669 with token text below.'),ev('components/GatePassView.tsx',2,'react-qr-code import.'),ev('components/GatePassView.tsx',274,'QRCode value=selectedGatePass.qrToken in dedicated view.')],['Container 360 > Gate Pass'],
  `import QRCode from 'react-qr-code';\n<div className="inline-block rounded-xl border border-slate-200 bg-white p-4">\n  {activeVisitGatePass.qrToken ? (\n    <QRCode value={activeVisitGatePass.qrToken} size={160}\n      title={\`QR phiếu ra cổng \${activeVisitGatePass.code}\`} />\n  ) : <p>QR chưa khả dụng. Mở Phiếu ra cổng để kiểm tra.</p>}\n</div>`,['Decode QR in both screens in a disposable fixture; decoded value equals the same qrToken.','No token/permission: display honest unavailable text and a route to dedicated Gate Pass.','Keep a readable code alternative and expiration guidance.'],['H1','H4','H5'],{principle:'Jakob',friction:'A familiar scannable code affordance produces no encoded business value.',change:'Render the existing QR component or label an icon as decorative.'});
add(10,'P2','states','kz A4; explicit readiness status','Container Gate Pass tab calls unknown readiness a failed condition',
  'Overview distinguishes checking, result and no result. The Gate Pass tab branches only on readiness?.blockers.length === 0; both null/pending and failed network check fall into copy saying unmet conditions are blocking issue. No checking/error branch is rendered in that tab. Unknown evaluation is therefore stated as a business blocker.',
  [ev('components/ContainersView.tsx',409,'Overview correctly distinguishes checking/no result.'),ev('components/ContainersView.tsx',679,'Gate Pass branch tests only blockers length.'),ev('components/ContainersView.tsx',729,'Fallback claims unmet conditions for all non-pass states.'),ev('components/useBackendReadiness.ts',13,'Hook clears readiness on each visit/reload and reports readinessError.')],['Container 360 > Gate Pass during check/error'],
  `{isCheckingReadiness ? (\n  <p role="status">Đang kiểm tra điều kiện ra cổng…</p>\n) : readinessError ? (\n  <p role="alert" className="text-rose-700">{readinessError}</p>\n) : !readiness ? (\n  <p>Chưa có kết quả kiểm tra. Vui lòng thử lại.</p>\n) : readiness.blockers.length > 0 ? (\n  <ul>{readiness.blockers.map(code => <li key={code}>{readinessLabel(code)}</li>)}</ul>\n) : <>{/* Existing issue form */}</>}`,['Pending/read failure/no result/blockers/pass each produce distinct truthful content.','A network error never becomes a claimed failed business condition.','Issue remains unavailable until an explicit backend pass.'],['H1','H9'],{principle:'Peak-End',friction:'Users are sent to fix business conditions before any result exists.',change:'Give pending and unknown their own states.'});
add(11,'P2','forms','Local datetime semantics; kz F2','Movement Order default expiry shifts the local clock by seven hours',
  'The datetime-local default is built using toISOString().slice(0,16), which removes the UTC zone but presents the UTC clock as a local value. Submission then parses that value as local and converts it back to UTC. On the workspace Asia/Saigon UTC+07 zone, the default intended now+24h becomes now+17h. Source proves this timezone transformation; real-browser displayed date was not measured by this agent.',
  [ev('components/MovementOrdersView.tsx',14,'UTC ISO string stripped for datetime-local.'),ev('components/MovementOrdersView.tsx',61,'datetime-local uses this value.'),ev('components/MovementOrdersView.tsx',111,'Selected local value is parsed then converted to ISO.')],['Movement Order > default authorization expiry'],
  `function localDateTimeValue(date: Date) {\n  const pad = (value: number) => String(value).padStart(2, '0');\n  return \`\${date.getFullYear()}-\${pad(date.getMonth() + 1)}-\${pad(date.getDate())}T\${pad(date.getHours())}:\${pad(date.getMinutes())}\`;\n}\nconst [expiresAt, setExpiresAt] = useState(() =>\n  localDateTimeValue(new Date(Date.now() + 86400000)));\n<label>Thời hạn khi duyệt lệnh (giờ thiết bị)\n  <input type="datetime-local" value={expiresAt}\n    onChange={event => setExpiresAt(event.target.value)} />\n</label>`,['Freeze a clock in UTC+07 and inspect the default: exactly 24h later, not 17h.','Edit local datetime and verify serialized ISO denotes that local clock time.','Blank/invalid/past dates show a recoverable error and do not submit.'],['H2','H5'],{principle:'Postel / Tesler',friction:'The system converts a default time into a different operational deadline.',change:'Format local datetime correctly and state the timezone.'},{workspace_offset_hours:7,default_intended_hours:24,default_serialized_hours:17});
add(12,'P2','navigation','kz N4; contextual navigation','Work Queue handover review passes the wrong identifier kind',
  'HANDOVER_REVIEW fallback navigation sends task.containerVisitId. App forwards the generic context as targetHandoverId. Handovers resolves this exclusively by handover.id, then falls back to the first handover. A task can therefore open an unrelated first handover instead of its review record. This is a source contract mismatch; whether fixture IDs happen to match remains runtime UNKNOWN.',
  [ev('components/WorkQueueView.tsx',81,'HANDOVER_REVIEW sends containerVisitId at 83.'),ev('App.tsx',53,'Generic activeContextId is targetHandoverId.'),ev('components/HandoversView.tsx',49,'Lookup compares h.id to targetHandoverId; fallback handovers[0].'),ev('components/HandoversView.tsx',53,'Effect repeats handover-id-only lookup.')],['Work Queue > Handover review'],
  `const { workQueue, currentUser, handovers } = useApp();\ncase 'HANDOVER_REVIEW': {\n  const handover = handovers.find(item =>\n    item.containerVisitId === task.containerVisitId && item.status === 'PARTNER_CONFIRMED');\n  if (!handover) { setNavigationError('Không tìm thấy bàn giao cần duyệt.'); break; }\n  onNavigate('handovers', handover.id);\n  break;\n}`,['With two distinct handovers, opening the second review task selects the second correct handover.','No matching target displays a missing/unavailable-target state rather than silently selecting the first record.','Prefer retaining canonical entityId in work-queue mapping if a visit can have multiple handovers.'],['H2','H3','H5'],{principle:'Tesler / Jakob',friction:'The navigation makes users rediscover the intended record and can select the wrong one.',change:'Pass/resolve a canonical handover identifier.'});
add(13,'P2','navigation','kz N4; promise/action alignment','Create Truck Visit shortcut drops its container context and opens no form',
  'Movement Order action says Tạo Truck Visit and sends containerVisitId, but App renders TruckVisitsView with only onNavigate; TruckVisitsView supports no context prop and initializes showCreateModal=false, selectedConts empty. Users arrive at a generic list and must reopen the form and retype the intended container. Truck Visit Gate-in shortcut also omits its linked visit, sending users to a blank selection.',
  [ev('components/MovementOrdersView.tsx',129,'Tạo Truck Visit navigation passes containerVisitId.'),ev('App.tsx',48,'TruckVisitsView receives no activeContextId.'),ev('components/TruckVisitsView.tsx',17,'Props contain onNavigate only.'),ev('components/TruckVisitsView.tsx',25,'Create modal initially false; selectedConts empty at 33.'),ev('components/TruckVisitsView.tsx',146,'Gate-in shortcut omits the container visit id.')],['Movement Order > Tạo Truck Visit','Truck Visit > Tiến hành Tiếp nhận'],
  `<TruckVisitsView onNavigate={handleNavigate} targetVisitId={activeContextId} />\n// In TruckVisitsView, add the optional targetVisitId prop.\nuseEffect(() => {\n  if (!targetVisitId) return;\n  const visit = containerVisits.find(item => item.id === targetVisitId);\n  if (!visit) return;\n  setSelectedConts(visit.containerNumber);\n  setType('GATE_IN'); setShowCreateModal(true);\n}, [targetVisitId, containerVisits]);`,['Authorized Movement Order shortcut opens create with the correct container prefilled.','Gate-in shortcut selects the relevant visit and matching arrived truck when unambiguous.','Missing or multiple matching targets have explicit selection/recovery; no write occurs on navigation.'],['H2','H6','H7'],{principle:'Tesler',friction:'Users must carry and re-enter data the application already knows.',change:'Propagate the context to the destination and perform the advertised opening action.'});
add(14,'P2','navigation','kz N4 / F3; browser history and return state','Screen/context selections are memory-only and view changes discard work',
  'App navigation changes local activeTab/activeContextId without router, URL or history. A reload starts at dashboard; browser Back cannot restore in-app selections. Conditional renderContent also unmounts most views, so their local filters, selections and form drafts disappear when navigating away and back. Partner CLIENTS/LOGS is the same component type and can retain state, so this is not claimed for that pair. Session state/data security resets are separate.',
  [ev('App.tsx',28,'activeTab default dashboard; context stored only in useState.'),ev('App.tsx',32,'handleNavigate only sets component state.'),ev('App.tsx',43,'Conditional view switch replaces most screen components.'),ev('components/ManifestsView.tsx',84,'Search and draft fields live in view useState.')],['All 18 sidebar destinations','Multi-field Manifest/Container/Truck/Handover drafts'],
  `const [params, setParams] = useSearchParams();\nconst activeTab = (params.get('view') || 'dashboard') as NavTabId;\nconst activeContextId = params.get('record') || undefined;\nconst handleNavigate = (tab: NavTabId, contextId?: string) => {\n  setParams({ view: tab, ...(contextId ? { record: contextId } : {}) });\n  setIsSidebarOpen(false);\n};\n// Wrap the app in the existing react-router-dom BrowserRouter.\n// Store per-view filters/drafts in parent state; restore them on return.`,['Navigate A>B, use browser Back: A and its record/filter/scroll selection restore.','A copied URL or reload opens the requested authorized destination and record.','Leaving a dirty multi-field form preserves a draft or gives an explicit discard choice.'],['H3','H6','H7'],{principle:'Zeigarnik / Jakob',friction:'Interrupted work restarts and standard browser return behavior cannot recover it.',change:'Address screens/context and retain view state using the installed router and local draft state.'});
add(15,'P2','states','kz A4; empty and no-results feedback','Several lists render a blank region for zero rows',
  'Audits and Master Data table bodies contain only mapped rows. Truck Visit cards, Partner clients/logs, Manifest list, Handover list, Gate Pass list and EDI outbox/routes similarly have no explicit collection/no-match branch at the list location. Existing detail placeholders ask users to choose a record even when no records exist. Global loading/error indicators do exist; this finding is specifically settled zero/no-match state.',
  [ev('components/AuditsView.tsx',61,'Only filteredLogs.map until tbody end 81.'),ev('components/MasterDataView.tsx',147,'tbody only renderList().'),ev('components/TruckVisitsView.tsx',95,'Only filteredVisits.map until list close 155.'),ev('components/PartnerManagementView.tsx',84,'Only partnerClients.map until 148; logs at 243.'),ev('components/ManifestsView.tsx',200,'Only filtered map in list.'),ev('components/HandoversView.tsx',211,'Only filtered map in list.'),ev('components/GatePassView.tsx',200,'Only filtered map in list.'),ev('components/EDIView.tsx',205,'Only filteredEdi.map; routes map at 121.')],['Audit list','Master Data list','Truck Visit list','Partner clients/logs','Manifest list','Handover list','Gate Pass list','EDI outbox/routes'],
  `{filteredLogs.length === 0 && (\n  <tr><td colSpan={6} className="px-4 py-10 text-center text-slate-500">\n    {searchTerm ? 'Không có bản ghi khớp tìm kiếm.' : 'Chưa có nhật ký kiểm toán.'}\n    {searchTerm && <button type="button" onClick={() => setSearchTerm('')}\n      className="ml-2 font-semibold text-blue-700 underline">Xóa tìm kiếm</button>}\n  </td></tr>\n)}`,['Fixture 0 records and a nonempty collection filtered to 0 each render distinct messages.','No-results recovery clears the actual filters without initiating a write.','Loading/error/forbidden states are not described as an empty collection.'],['H1','H9'],{principle:'Peak-End / Gestalt closure',friction:'A blank region gives no outcome or recovery for search/list loading completion.',change:'Explain settled empty and no-match states with context-appropriate next steps.'});
add(16,'P1','states','kz A4; partial data integrity','Nested load failures silently become empty holds, passes or incomplete details',
  'The top-level loader records failures, but later per-visit holds/gate-pass requests use allSettled and substitute [] without adding to failures. Manifest bills, role detail and handover detail also catch and return the less-complete row with no local availability marker. After such a rejected GET, UI can show no holds or no pass rather than unavailable data while apiError remains empty if other requests succeeded. Backend readiness/Gate-out rechecks still enforce business rules.',
  [ev('context/AppContext.tsx',365,'Manifest detail catch returns m at 370 with no marker.'),ev('context/AppContext.tsx',373,'Role detail catch returns r at 375.'),ev('context/AppContext.tsx',377,'Handover detail catch returns h at 379.'),ev('context/AppContext.tsx',391,'Rejected holds/passes become [] at 393; no failures.push.'),ev('context/AppContext.tsx',409,'Banner depends on failures and health only.')],['Container Holds/Gate Pass','Yard HOLD appearance','Manifest MBL/HBL detail','Role permission detail','Handover review detail'],
  `const perVisit = await Promise.all(visits.map(async visit => {\n  const paths = [\`/containers/\${visit.id}/holds\`, \`/containers/\${visit.id}/gate-passes\`];\n  const results = await Promise.allSettled(paths.map(loadList));\n  results.forEach((result, index) => {\n    if (result.status === 'rejected' && ![401, 403].includes(result.reason?.status))\n      failures.push(\`\${paths[index]}: \${result.reason?.message ?? 'Không tải được dữ liệu'}\`);\n  });\n  return {\n    holds: results[0].status === 'fulfilled' ? results[0].value : [],\n    passes: results[1].status === 'fulfilled' ? results[1].value : [],\n    holdsLoaded: results[0].status === 'fulfilled', passesLoaded: results[1].status === 'fulfilled',\n  };\n}));\n// Preserve these per-record availability flags so empty is distinct from unavailable.`,['Reject one nested GET in a fixture while top-level/health succeed: show partial/unavailable state and retry.','A failed holds request must not claim no holds or derive a reassuring no-HOLD appearance.','Distinguish permission restriction from transient failure without exposing unauthorized details.'],['H1','H5','H9'],{principle:'Peak-End',friction:'Incomplete operational data is presented with the visual confidence of an empty complete result.',change:'Retain per-record readiness/availability markers and report partial failures.'});
add(17,'P1','microcopy','Truthful source attribution; kz A4','EDI inspector calls generated example segments the raw transmitted payload',
  'getSimulatedEdifact constructs segments from UI fields and hardcodes EQD ISO type 45G1 and other envelope values. Both Copy and the panel labelled raw UN/EDIFACT payload use that function rather than the actual outbound message. An operator inspecting a 20-foot/reefer message can therefore copy a generated 40HC example presented as source-of-truth transmission data.',
  [ev('components/EDIView.tsx',30,'getSimulatedEdifact constructs payload, hardcodes 45G1 at 36.'),ev('components/EDIView.tsx',262,'Copy copies simulated output.'),ev('components/EDIView.tsx',303,'Panel says raw segment payload; render at 306 uses generator.')],['EDI Outbox > payload inspector/Copy'],
  `<div className="mb-2 text-xs font-bold text-slate-700">\n  Bản minh họa EDIFACT — không phải payload đã truyền\n</div>\n<p className="mb-2 text-xs text-amber-800">\n  Dữ liệu dưới đây được tạo để minh họa. Xem payload gốc từ backend khi khả dụng.\n</p>\n<button type="button" onClick={() => handleCopy(getSimulatedEdifact(selectedEdi))}>\n  Sao chép bản minh họa\n</button>\n<pre>{getSimulatedEdifact(selectedEdi)}</pre>`,['A generated preview is visibly and accessibly identified as illustrative before copying.','If raw payload becomes available, display exactly that payload and clearly identify its version/source.','A 20-foot/reefer fixture never labels a hardcoded 45G1 example as its transmitted raw data.'],['H1','H2','H5'],{principle:'Jakob / Peak-End',friction:'An inspection tool labels reconstructed illustrative data as authoritative output.',change:'Show the real backend payload or clearly name the illustrative preview.'});
add(18,'P2','states','kz A4; permission-aware actions','Read-only page access still exposes write actions',
  'Sidebar page permission checks distinguish read from write, but Users/Roles, Master Data and Billing show creation/toggle/edit controls without checking the corresponding write permissions. Read-only users may enter these pages and are invited to actions the API will reject. This is an interaction/permission-state issue, not a claim that the backend is insecure. Yard already demonstrates exact permission gating.',
  [ev('services/permissions.ts',4,'Billing page requires billing.read.'),ev('services/permissions.ts',7,'Master Data read; Users/Roles read permits page.'),ev('components/UsersRolesView.tsx',43,'Add User unconditional once USERS tab.'),ev('components/UsersRolesView.tsx',80,'User role/status write controls unconditional; permissions editor at 114/129.'),ev('components/MasterDataView.tsx',110,'Add new and per-row toggle unconditional.'),ev('components/BillingView.tsx',212,'Payment action depends on invoice status, not billing.manage.')],['Users/Roles read-only','Master Data read-only','Billing read-only'],
  `const { currentUser, ...data } = useApp();\nconst canManageUsers = currentUser.permissionCodes?.some(code =>\n  code === '*' || code === 'users.manage') ?? false;\n{canManageUsers && (\n  <button type="button" onClick={() => setShowUserForm(true)}\n    className="rounded-lg bg-blue-600 px-3.5 py-2 text-xs font-bold text-white">\n    Thêm người dùng\n  </button>\n)}\n{/* Gate role writes with roles.manage, master data with master_data.manage. */}`,['Read-only fixture users see viewing controls and clear permission context, no unusable write invitation.','Users/manage, roles/manage, billing/manage and tariff/manage controls follow exact separate permissions.','Backend authorization remains enforced on every command.'],['H1','H5'],{principle:'Hick / Tesler',friction:'Unusable choices increase effort and end in predictable permission errors.',change:'Expose only authorized actions or explain unavailable actions before use.'});
add(19,'P2','navigation','kz N2; dismissible popover','Notifications panel lacks Escape and outside-click dismissal',
  'Header provides a correctly named trigger and aria-expanded, and the trigger can toggle the panel closed. However, its panel contains no Escape handler, outside-click listener or visible Done/close control. It can remain open over changed content until users rediscover the same trigger. A nonmodal panel does not require dialog/menu roles or focus trapping, so those are not claimed missing.',
  [ev('components/Header.tsx',9,'Only local showNotifs state.'),ev('components/Header.tsx',33,'Trigger toggles and exposes aria-expanded.'),ev('components/Header.tsx',34,'Panel has no dismissal routes beyond trigger; full component has no effect/keydown listener.')],['Header > Notifications'],
  `const notificationRef = useRef<HTMLDivElement>(null);\nuseEffect(() => {\n  if (!showNotifs) return;\n  const closeOnPointer = (event: PointerEvent) => {\n    if (!notificationRef.current?.contains(event.target as Node)) setShowNotifs(false);\n  };\n  const closeOnKey = (event: KeyboardEvent) => {\n    if (event.key === 'Escape') { setShowNotifs(false); notificationTrigger.current?.focus(); }\n  };\n  document.addEventListener('pointerdown', closeOnPointer);\n  document.addEventListener('keydown', closeOnKey);\n  return () => { document.removeEventListener('pointerdown', closeOnPointer); document.removeEventListener('keydown', closeOnKey); };\n}, [showNotifs]);\n<button type="button" onClick={() => setShowNotifs(false)}>Đóng thông báo</button>`,['Open panel: trigger again, real Escape and outside pointer each close.','Escape returns focus to trigger; a visible touch close route stays reachable.','Click inside keeps appropriate content interactions working and does not lock the main page.'],['H3','H4'],{principle:'Jakob',friction:'A familiar popup does not follow standard dismissal routes.',change:'Add dismissal and a reachable explicit close control without modal behavior.'});

